sql_calls.sql:
SELECT table_name 
FROM information_schema.tables 
WHERE table_schema = 'store' AND table_type = 'BASE TABLE';

SELECT SUM(line_amount) AS may_total_sales 
FROM store.pos_lines 
WHERE bill_ts >= '2026-05-01' AND bill_ts < '2026-06-01';

SELECT COUNT(*) FROM store.stock_counts 
WHERE count_ts >= '2026-06-01' AND count_ts < '2026-07-01' 
AND trigger = 'manager request after complaints';

SELECT COUNT(*) AS goods_receipt_lines
FROM warehouse.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT sku, name, flow, price_inr, cost_inr 
FROM store.products 
WHERE name ILIKE '%toned%' OR flow ILIKE '%toned%';

SELECT COUNT(*) AS goods_receipt_lines
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT COUNT(DISTINCT date) AS days_with_write_offs
FROM store.write_offs
WHERE date >= '2026-06-01' AND date < '2026-07-01';

